// Safely retrieve environment variables or default to empty string
// This handles scenarios where process is undefined or variables are missing
const getEnv = (key: string) => {
  try {
    if (typeof process !== 'undefined' && process.env && process.env[key]) {
      return process.env[key];
    }
  } catch (e) {
    // process not defined
  }
  return '';
};

const supabaseUrl = getEnv('SUPABASE_URL');
const supabaseAnonKey = getEnv('SUPABASE_ANON_KEY');

// Initialize client with placeholders if keys are missing to prevent 'supabaseUrl is required' error on load.
