import React, { useState, useEffect } from 'react';
import { api } from '../../utils/api';
import { ComponentVariant } from '../../types';

interface CRMData {
  appointments: any[];
  preorders: any[];
  inquiries: any[];
  corporate: any[];
}

export const CRMManager: React.FC = () => {
  const [activeTab, setActiveTab] = useState('appointments');
  const [data, setData] = useState<CRMData>({ appointments: [], preorders: [], inquiries: [], corporate: [] });
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    setLoading(true);
    const [apps, pre, inq, corp] = await Promise.all([
      api.get('/appointments'),
      api.get('/preorders'),
      api.get('/inquiries'),
      api.get('/corporate-requests')
    ]);

    setData({
      appointments: apps.success ? apps.data : [],
      preorders: pre.success ? pre.data : [],
      inquiries: inq.success ? inq.data : [],
      corporate: corp.success ? corp.data : []
    });
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, []);

  const TABS = [
    { id: 'appointments', label: 'Appointments' },
    { id: 'preorders', label: 'Pre-Orders' },
    { id: 'corporate', label: 'Corporate' },
    { id: 'inquiries', label: 'Inquiries' },
  ];

  const renderTable = () => {
    if (loading) return <div className="p-8 text-center text-slate-500">Loading CRM data...</div>;

    let items = [];
    let columns: any[] = [];

    switch (activeTab) {
      case 'appointments':
        items = data.appointments;
        columns = [
          { header: 'Name', accessor: (i:any) => i.full_name },
          { header: 'Date', accessor: (i:any) => i.appointment_date || 'Pending' },
          { header: 'Type', accessor: (i:any) => i.visit_type },
          { header: 'Contact', accessor: (i:any) => i.email }
        ];
        break;
      case 'preorders':
        items = data.preorders;
        columns = [
          { header: 'Customer', accessor: (i:any) => i.full_name },
          { header: 'Vehicle', accessor: (i:any) => `${i.brand} ${i.model || ''}` },
          { header: 'Color', accessor: (i:any) => i.color || '-' },
          { header: 'Date', accessor: (i:any) => new Date(i.created_at).toLocaleDateString() }
        ];
        break;
      case 'corporate':
        items = data.corporate;
        columns = [
          { header: 'Company', accessor: (i:any) => i.company_name },
          { header: 'Contact', accessor: (i:any) => i.contact_person },
          { header: 'Fleet Size', accessor: (i:any) => i.fleet_size_interest },
          { header: 'Status', accessor: (i:any) => i.status }
        ];
        break;
      case 'inquiries':
        items = data.inquiries;
        columns = [
          { header: 'From', accessor: (i:any) => i.name },
          { header: 'Subject', accessor: (i:any) => i.subject || 'General' },
          { header: 'Status', accessor: (i:any) => i.status },
          { header: 'Date', accessor: (i:any) => new Date(i.created_at).toLocaleDateString() }
        ];
        break;
    }

    if (items.length === 0) return <div className="p-12 text-center text-slate-500 bg-white/5 rounded-xl border border-dashed border-white/10">No records found.</div>;

    return (
      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead className="bg-white/5 text-xs text-slate-400 uppercase tracking-widest">
            <tr>
              {columns.map((col, idx) => (
                <th key={idx} className="p-4 font-medium">{col.header}</th>
              ))}
              <th className="p-4 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5 text-sm">
            {items.map((item: any) => (
              <tr key={item.id} className="hover:bg-white/5 transition-colors">
                {columns.map((col, idx) => (
                  <td key={idx} className="p-4 text-slate-300">{col.accessor(item)}</td>
                ))}
                <td className="p-4 text-right">
                   <button className="text-emphathon-rust hover:text-white transition-colors text-xs font-bold uppercase tracking-wider">
                      Details
                   </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  return (
    <div className="bg-emphathon-navy/50 h-full flex flex-col">
      <div className="flex items-center gap-4 mb-6 border-b border-white/10 pb-4">
        {TABS.map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
              activeTab === tab.id 
                ? 'bg-emphathon-rust text-white shadow-lg shadow-emphathon-rust/20' 
                : 'text-slate-400 hover:bg-white/5 hover:text-white'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className="flex-1 bg-white/5 border border-white/10 rounded-2xl p-6 overflow-hidden">
        {renderTable()}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { api } from '../../utils/api';
import { Button } from '../Button';
import { ComponentVariant } from '../../types';

export const ContentManager: React.FC = () => {
  const [section, setSection] = useState<'hero' | 'testimonials'>('hero');
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  const fetchData = async () => {
    setLoading(true);
    const endpoint = section === 'hero' ? '/hero-media' : '/testimonials';
    const res = await api.get(endpoint);
    if (res.success) setData(res.data);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, [section]);

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this item?')) return;
    const endpoint = section === 'hero' ? `/hero-media/${id}` : `/testimonials/${id}`;
    await api.delete(endpoint);
    fetchData();
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <div className="flex bg-black/20 p-1 rounded-lg border border-white/10">
          <button 
            onClick={() => setSection('hero')}
            className={`px-6 py-2 rounded-md text-sm transition-all ${section === 'hero' ? 'bg-emphathon-rust text-white shadow' : 'text-slate-400'}`}
          >
            Hero Slides
          </button>
          <button 
            onClick={() => setSection('testimonials')}
            className={`px-6 py-2 rounded-md text-sm transition-all ${section === 'testimonials' ? 'bg-emphathon-rust text-white shadow' : 'text-slate-400'}`}
          >
            Testimonials
          </button>
        </div>
        <Button variant={ComponentVariant.PRIMARY} className="!py-2 !px-4 !text-sm">
           Create New {section === 'hero' ? 'Slide' : 'Testimonial'}
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 overflow-auto pb-8">
        {loading ? (
          <div className="col-span-3 text-center text-slate-500 py-12">Loading content...</div>
        ) : (
          data.map((item: any) => (
            <div key={item.id} className="bg-white/5 border border-white/10 rounded-xl overflow-hidden group hover:border-emphathon-rust/50 transition-colors">
              {section === 'hero' ? (
                <>
                  <div className="h-40 bg-black/40 relative">
                    <img src={item.image_url} alt={item.title} className="w-full h-full object-cover opacity-80" />
                    <div className="absolute top-2 right-2 px-2 py-1 bg-black/60 rounded text-[10px] uppercase text-white backdrop-blur">
                       {item.is_active ? 'Active' : 'Draft'}
                    </div>
                  </div>
                  <div className="p-4">
                    <h3 className="text-white font-bold mb-1 truncate">{item.title}</h3>
                    <p className="text-slate-400 text-xs line-clamp-2 mb-4">{item.subtitle}</p>
                    <div className="flex justify-end gap-2">
                       <button className="text-xs text-slate-400 hover:text-white px-3 py-1 bg-white/5 rounded">Edit</button>
                       <button onClick={() => handleDelete(item.id)} className="text-xs text-red-400 hover:text-red-300 px-3 py-1 bg-white/5 rounded">Delete</button>
                    </div>
                  </div>
                </>
              ) : (
                <div className="p-6 flex flex-col h-full">
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-full bg-white/10 overflow-hidden">
                       {item.avatar_url && <img src={item.avatar_url} className="w-full h-full object-cover" />}
                    </div>
                    <div>
                      <h4 className="text-white font-bold text-sm">{item.client_name}</h4>
                      <p className="text-slate-500 text-xs">{item.role}</p>
                    </div>
                  </div>
                  <p className="text-slate-300 text-sm mb-4 flex-1 italic">"{item.content}"</p>
                  <div className="flex items-center justify-between border-t border-white/10 pt-4">
                     <span className="text-emphathon-rust text-xs font-bold">{item.rating} Stars</span>
                     <button onClick={() => handleDelete(item.id)} className="text-red-400 hover:text-red-300 text-xs">Delete</button>
                  </div>
                </div>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

