                <span className={`flex-shrink-0 ml-4 w-6 h-6 rounded-full flex items-center justify-center border transition-all duration-300 ${
                  activeIndex === index 
                    ? 'border-empathon-rust bg-empathon-rust text-white rotate-180' 
