export const ContactForm: React.FC = () => {
  const [method, setMethod] = useState<'Walk-in' | 'Pre-Order'>('Walk-in');
  const [buyerType, setBuyerType] = useState<'Corporate' | 'Individual'>('Individual');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [success, setSuccess] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    date: '',
    message: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSuccess(false);

    // Assuming we have an 'appointments' table
    const { error } = await supabase
      .from('appointments')
      .insert([
        {
          full_name: formData.name,
          email: formData.email,
          phone: formData.phone,
          appointment_date: formData.date ? formData.date : null,
          message: formData.message,
          visit_type: method,
          buyer_type: buyerType
        }
      ]);

    setIsSubmitting(false);

    if (error) {
      console.error('Error booking appointment:', error);
      alert('Could not schedule appointment. Please try again.');
    } else {
      setSuccess(true);
      setFormData({ name: '', email: '', phone: '', date: '', message: '' });
      setTimeout(() => setSuccess(false), 5000);
    }
  };

  const inputClasses = "w-full bg-white/5 border border-white/10 rounded-lg px-4 py-3 text-white placeholder-slate-600 focus:outline-none focus:border-empathon-rust focus:ring-1 focus:ring-empathon-rust transition-all duration-300 hover:bg-white/[0.07]";
