import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { HeroSlider } from './components/HeroSlider';
import { CarGrid } from './components/CarGrid';
import { CorporateFleet } from './components/CorporateFleet';
import { IndividualCTA } from './components/IndividualCTA';
import { Testimonials } from './components/Testimonials';
import { FAQ } from './components/FAQ';
import { ReservationForm } from './components/ReservationForm';
import { ContactForm, AppointmentBlock } from './components/ContactSection';
import { Footer } from './components/Footer';
import { AdminDashboard } from './components/admin/AdminDashboard';
import { AdminLogin } from './components/admin/AdminLogin';

const App: React.FC = () => {
  const [isAdminRoute, setIsAdminRoute] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [showScrollTop, setShowScrollTop] = useState(false);

  useEffect(() => {
    // Check for existing session
    const session = localStorage.getItem('empathon_admin_session');
    if (session === 'valid') {
      setIsAuthenticated(true);
    }
    setIsLoading(false);

    // Hash-based router check
    const checkHash = () => {
      setIsAdminRoute(window.location.hash === '#admin');
    };

    checkHash();
    window.addEventListener('hashchange', checkHash);

    // Scroll listener for "Back to Top" button
    const handleScroll = () => {
      if (window.scrollY > 500) {
        setShowScrollTop(true);
      } else {
        setShowScrollTop(false);
      }
    };
    window.addEventListener('scroll', handleScroll);

    return () => {
      window.removeEventListener('hashchange', checkHash);
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  const handleLogin = () => {
    localStorage.setItem('empathon_admin_session', 'valid');
    setIsAuthenticated(true);
  };

  const scrollToTop = () => {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  };

  if (isLoading) return null; // Or a loading spinner

  if (isAdminRoute) {
    if (!isAuthenticated) {
      return <AdminLogin onLogin={handleLogin} />;
    }
    return <AdminDashboard />;
  }

  return (
    <div className="bg-empathon-navy min-h-screen text-white font-sans selection:bg-empathon-rust selection:text-white overflow-x-hidden relative">
      <Navbar />

      <main>
        <HeroSlider />
        <CarGrid />
        <CorporateFleet />
        <IndividualCTA />
        <Testimonials />
        <FAQ />
        <ReservationForm />

        {/* Phase 7: Contact & Appointment Section */}
        <section id="contact" className="py-24 max-w-[1920px] mx-auto px-6 md:px-12 relative z-10">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-24 items-start">
             <AppointmentBlock />
             <ContactForm />
          </div>
        </section>

      </main>

      <Footer />

      {/* Scroll to Top Button */}
      <button 
        onClick={scrollToTop}
        className={`fixed bottom-8 right-8 z-40 w-12 h-12 bg-empathon-rust text-white rounded-full shadow-lg shadow-black/30 flex items-center justify-center border border-white/20 transition-all duration-500 transform hover:scale-110 hover:bg-empathon-rustLight ${
          showScrollTop ? 'translate-y-0 opacity-100' : 'translate-y-20 opacity-0 pointer-events-none'
        }`}
      >
        <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
        </svg>
      </button>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { api } from '../../utils/api';
import { Button } from '../Button';
import { ComponentVariant } from '../../types';

export const ContentManager: React.FC = () => {
  const [section, setSection] = useState<'hero' | 'testimonials'>('hero');
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [isCreating, setIsCreating] = useState(false);

  // Form State
  const [newItem, setNewItem] = useState<any>({});

  const fetchData = async () => {
    setLoading(true);
    const endpoint = section === 'hero' ? '/hero-media' : '/testimonials';
    const res = await api.get(endpoint);
    if (res.success) setData(res.data);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    setIsCreating(false);
    setNewItem({});
  }, [section]);

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this item?')) return;
    const endpoint = section === 'hero' ? `/hero-media/${id}` : `/testimonials/${id}`;
    await api.delete(endpoint);
    fetchData();
  };

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const endpoint = section === 'hero' ? '/hero-media' : '/testimonials';

    // Default values
    const payload = section === 'hero' ? {
       title: newItem.title,
       subtitle: newItem.subtitle,
       image_url: newItem.image_url,
       cta_primary_text: newItem.cta_primary_text || 'View Inventory',
       cta_secondary_text: newItem.cta_secondary_text || 'Contact Us',
       display_order: data.length + 1
    } : {
       client_name: newItem.client_name,
       role: newItem.role,
       content: newItem.content,
       rating: Number(newItem.rating) || 5,
       client_type: newItem.client_type || 'Individual',
       avatar_url: newItem.avatar_url
    };

    const res = await api.post(endpoint, payload);

    if (res.success) {
      setIsCreating(false);
      setNewItem({});
      fetchData();
    } else {
      alert('Failed to create item');
    }
    setLoading(false);
  };

  const inputClass = "w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:outline-none focus:border-emphathon-rust";
  const labelClass = "block text-xs text-slate-400 uppercase tracking-widest mb-2";

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <div className="flex bg-black/20 p-1 rounded-lg border border-white/10">
          <button 
            onClick={() => setSection('hero')}
            className={`px-6 py-2 rounded-md text-sm transition-all ${section === 'hero' ? 'bg-emphathon-rust text-white shadow' : 'text-slate-400'}`}
          >
            Hero Slides
          </button>
          <button 
            onClick={() => setSection('testimonials')}
            className={`px-6 py-2 rounded-md text-sm transition-all ${section === 'testimonials' ? 'bg-emphathon-rust text-white shadow' : 'text-slate-400'}`}
          >
            Testimonials
          </button>
        </div>
        {!isCreating && (
          <Button variant={ComponentVariant.PRIMARY} className="!py-2 !px-4 !text-sm" onClick={() => setIsCreating(true)}>
            Create New {section === 'hero' ? 'Slide' : 'Testimonial'}
          </Button>
        )}
      </div>

      {isCreating ? (
        <div className="flex-1 overflow-auto">
          <div className="max-w-2xl mx-auto bg-white/5 border border-white/10 rounded-2xl p-8">
            <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-serif text-white">Add New {section === 'hero' ? 'Hero Slide' : 'Testimonial'}</h3>
               <button onClick={() => setIsCreating(false)} className="text-slate-400 hover:text-white">Cancel</button>
            </div>

            <form onSubmit={handleCreate} className="space-y-6">
              {section === 'hero' ? (
                <>
                  <div>
                    <label className={labelClass}>Title</label>
                    <input required type="text" className={inputClass} placeholder="e.g. The New GLE 350" value={newItem.title || ''} onChange={e => setNewItem({...newItem, title: e.target.value})} />
                  </div>
                  <div>
                    <label className={labelClass}>Subtitle</label>
                    <textarea required className={inputClass} rows={2} placeholder="Description text..." value={newItem.subtitle || ''} onChange={e => setNewItem({...newItem, subtitle: e.target.value})} />
                  </div>
                  <div>
                    <label className={labelClass}>Image URL (Unsplash or direct link)</label>
