                  </div>
                </>
              )}

              <Button type="submit" disabled={loading || uploading} variant={ComponentVariant.PRIMARY} className="w-full justify-center">
                {loading || uploading ? 'Processing...' : (editingId ? 'Save Changes' : 'Create')}
              </Button>
            </form>
          </div>
        </div>
      ) : (
