  const [loading, setLoading] = useState(false);

  // State for Create/Edit
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);

  // Form State
  const [formData, setFormData] = useState<any>({});

  // File states
  const [heroFile, setHeroFile] = useState<File | null>(null);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [carFile, setCarFile] = useState<File | null>(null);

  const fetchData = async () => {
    setLoading(true);
    const table = section === 'hero' ? 'hero_media' : 'testimonials';
    const { data: result, error } = await supabase.from(table).select('*').order('created_at', { ascending: false });

    if (!error && result) {
      setData(result);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    resetForm();
  }, [section]);

  const resetForm = () => {
    setIsFormOpen(false);
    setEditingId(null);
    setFormData({});
    setHeroFile(null);
    setAvatarFile(null);
    setCarFile(null);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this item?')) return;
    const table = section === 'hero' ? 'hero_media' : 'testimonials';
    await supabase.from(table).delete().eq('id', id);
    fetchData();
  };

  const handleEdit = (item: any) => {
    setEditingId(item.id);
    setFormData(item);
    setIsFormOpen(true);
    // Clear files so we don't accidentally re-upload unless changed
    setHeroFile(null);
    setAvatarFile(null);
    setCarFile(null);
  };

  const uploadFile = async (file: File, folder: string): Promise<string> => {
    try {
      setUploading(true);
      const fileExt = file.name.split('.').pop();
      const fileName = `${folder}/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

      const { error: uploadError } = await supabase.storage
        .from('media')
        .upload(fileName, file);

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('media').getPublicUrl(fileName);
      return data.publicUrl;
    } catch (error) {
      console.error('Upload failed:', error);
      alert(`Image upload failed: ${error}`);
      return '';
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // VALIDATION: Ensure image is present for new Hero items
    if (section === 'hero' && !editingId && !heroFile && !formData.image_url) {
      alert("Please upload a slide image to continue.");
      return;
    }

    setLoading(true);
    const table = section === 'hero' ? 'hero_media' : 'testimonials';

    let payload = { ...formData };

    // Handle Uploads
    if (section === 'hero') {
      if (heroFile) {
        const url = await uploadFile(heroFile, 'hero');
        if (url) payload.image_url = url;
        else {
           setLoading(false);
           return; // Upload failed
        }
      }
      // Ensure defaults
      payload.cta_primary_text = payload.cta_primary_text || 'View Inventory';
      payload.cta_secondary_text = payload.cta_secondary_text || 'Contact Us';
      if (!editingId) payload.display_order = data.length + 1;

      // Clean up fields from other section
      delete payload.client_name; delete payload.role; delete payload.content; delete payload.avatar_url; delete payload.car_purchased_image_url;
    } else {
      if (avatarFile) {
        const url = await uploadFile(avatarFile, 'avatars');
        if (url) payload.avatar_url = url;
      }
      if (carFile) {
        const url = await uploadFile(carFile, 'testimonials');
        if (url) payload.car_purchased_image_url = url;
      }
      payload.rating = Number(payload.rating) || 5;
      payload.client_type = payload.client_type || 'Individual';

      delete payload.title; delete payload.subtitle; delete payload.image_url; delete payload.cta_primary_text; delete payload.cta_secondary_text;
    }

    let error;

    if (editingId) {
       // Supabase Update
       const { error: updateError } = await supabase.from(table).update(payload).eq('id', editingId);
       error = updateError;
    } else {
       // Supabase Insert
       const { error: insertError } = await supabase.from(table).insert([payload]);
       error = insertError;
    }

    if (!error) {
      resetForm();
      fetchData();
    } else {
      alert(`Failed to save item: ${error.message}`);
      console.error(error);
    }
    setLoading(false);
  };

  const inputClass = "w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:outline-none focus:border-empathon-rust";
  const labelClass = "block text-xs text-slate-400 uppercase tracking-widest mb-2";

  return (
    <div className="h-full flex flex-col">
      <div className="flex justify-between items-center mb-6 shrink-0">
        <div className="flex bg-black/20 p-1 rounded-lg border border-white/10">
          <button 
            onClick={() => { setSection('hero'); resetForm(); }}
            className={`px-6 py-2 rounded-md text-sm transition-all ${section === 'hero' ? 'bg-empathon-rust text-black shadow' : 'text-slate-400'}`}
          >
            Hero Slides
          </button>
          <button 
            onClick={() => { setSection('testimonials'); resetForm(); }}
            className={`px-6 py-2 rounded-md text-sm transition-all ${section === 'testimonials' ? 'bg-empathon-rust text-black shadow' : 'text-slate-400'}`}
          >
            Testimonials
          </button>
        </div>
        {!isFormOpen && (
          <Button variant={ComponentVariant.PRIMARY} className="!py-2 !px-4 !text-sm" onClick={() => setIsFormOpen(true)}>
            Create New {section === 'hero' ? 'Slide' : 'Testimonial'}
          </Button>
        )}
      </div>

      {isFormOpen ? (
        <div className="flex-1 overflow-auto min-h-0">
          <div className="max-w-2xl mx-auto bg-white/5 border border-white/10 rounded-2xl p-8">
            <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-serif text-white">{editingId ? 'Edit' : 'Add New'} {section === 'hero' ? 'Hero Slide' : 'Testimonial'}</h3>
               <button onClick={resetForm} className="text-slate-400 hover:text-white">Cancel</button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              {section === 'hero' ? (
                <>
                  <div>
                    <label className={labelClass}>Title</label>
                    <input required type="text" className={inputClass} placeholder="e.g. The New GLE 350" value={formData.title || ''} onChange={e => setFormData({...formData, title: e.target.value})} />
                  </div>
                  <div>
                    <label className={labelClass}>Subtitle</label>
                    <textarea required className={inputClass} rows={2} placeholder="Description text..." value={formData.subtitle || ''} onChange={e => setFormData({...formData, subtitle: e.target.value})} />
                  </div>

                  <div className="p-4 bg-white/5 rounded-xl border border-white/10">
                    <label className={labelClass}>Slide Image {(!editingId && !formData.image_url) && <span className="text-empathon-rust">*</span>}</label>
                    <input 
                      type="file" 
                      accept="image/*"
                      className="block w-full text-sm text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-empathon-rust file:text-black hover:file:bg-empathon-rustLight"
                      onChange={(e) => e.target.files && setHeroFile(e.target.files[0])}
                    />
                    {(heroFile || formData.image_url) && (
                      <div className="mt-2 h-24 w-full bg-black/40 rounded overflow-hidden relative">
                         <img src={heroFile ? URL.createObjectURL(heroFile) : formData.image_url} className="h-full w-full object-contain" />
                      </div>
                    )}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className={labelClass}>Primary Button Text</label>
                      <input type="text" className={inputClass} placeholder="View Inventory" value={formData.cta_primary_text || ''} onChange={e => setFormData({...formData, cta_primary_text: e.target.value})} />
                    </div>
                    <div>
                      <label className={labelClass}>Secondary Button Text</label>
                      <input type="text" className={inputClass} placeholder="Contact Us" value={formData.cta_secondary_text || ''} onChange={e => setFormData({...formData, cta_secondary_text: e.target.value})} />
                    </div>
                  </div>
                </>
              ) : (
                 <>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className={labelClass}>Client Name</label>
                      <input required type="text" className={inputClass} placeholder="e.g. John Doe" value={formData.client_name || ''} onChange={e => setFormData({...formData, client_name: e.target.value})} />
                    </div>
                    <div>
                      <label className={labelClass}>Client Type</label>
                      <select className={inputClass} value={formData.client_type || 'Individual'} onChange={e => setFormData({...formData, client_type: e.target.value})}>
                         <option value="Individual">Individual</option>
                         <option value="Corporate">Corporate</option>
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className={labelClass}>Role / Title</label>
                    <input type="text" className={inputClass} placeholder="e.g. CEO of TechCorp" value={formData.role || ''} onChange={e => setFormData({...formData, role: e.target.value})} />
                  </div>
                  <div>
                    <label className={labelClass}>Testimonial Content</label>
                    <textarea required className={inputClass} rows={3} placeholder="Quote..." value={formData.content || ''} onChange={e => setFormData({...formData, content: e.target.value})} />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                     <div className="p-3 bg-white/5 rounded-xl border border-white/10">
                        <label className={labelClass}>Client Avatar</label>
                        <input 
                           type="file" accept="image/*"
                           className="w-full text-xs text-slate-400 file:mr-2 file:py-1 file:px-2 file:rounded-full file:border-0 file:bg-empathon-rust file:text-black"
                           onChange={(e) => e.target.files && setAvatarFile(e.target.files[0])}
                        />
                         {(avatarFile || formData.avatar_url) && (
                           <div className="mt-2 h-16 w-16 rounded-full overflow-hidden bg-black/40">
                              <img src={avatarFile ? URL.createObjectURL(avatarFile) : formData.avatar_url} className="h-full w-full object-cover" />
                           </div>
                        )}
                     </div>
                     <div className="p-3 bg-white/5 rounded-xl border border-white/10">
                        <label className={labelClass}>Purchased Car Img</label>
                        <input 
                           type="file" accept="image/*"
                           className="w-full text-xs text-slate-400 file:mr-2 file:py-1 file:px-2 file:rounded-full file:border-0 file:bg-empathon-rust file:text-black"
                           onChange={(e) => e.target.files && setCarFile(e.target.files[0])}
                        />
                         {(carFile || formData.car_purchased_image_url) && (
                           <div className="mt-2 h-16 w-full rounded overflow-hidden bg-black/40">
                              <img src={carFile ? URL.createObjectURL(carFile) : formData.car_purchased_image_url} className="h-full w-full object-cover" />
                           </div>
                        )}
                     </div>
                  </div>

                  <div>
                    <label className={labelClass}>Rating (1-5)</label>
                    <input type="number" min="1" max="5" className={inputClass} value={formData.rating || 5} onChange={e => setFormData({...formData, rating: e.target.value})} />
                  </div>
                </>
              )}

              <Button type="submit" disabled={loading || uploading} variant={ComponentVariant.PRIMARY} className="w-full justify-center">
                {loading || uploading ? 'Processing...' : (editingId ? 'Save Changes' : 'Create')}
              </Button>
            </form>
          </div>
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto min-h-0">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 pb-24">
            {loading ? (
              <div className="col-span-3 text-center text-slate-500 py-12">Loading content...</div>
            ) : (
              data.map((item: any) => (
                <div key={item.id} className="bg-white/5 border border-white/10 rounded-xl overflow-hidden group hover:border-empathon-rust/50 transition-colors flex flex-col h-full">
                  {section === 'hero' ? (
                    <>
                      <div className="h-40 bg-black/40 relative shrink-0">
                        <img src={item.image_url} alt={item.title} className="w-full h-full object-cover opacity-80" />
                      </div>
                      <div className="p-4 flex flex-col flex-1">
                        <h3 className="text-white font-bold mb-1 truncate">{item.title}</h3>
                        <p className="text-slate-400 text-xs line-clamp-2 mb-4 flex-1">{item.subtitle}</p>
                        <div className="flex justify-end gap-2 pt-2 border-t border-white/5 shrink-0">
                           <button onClick={() => handleEdit(item)} className="text-xs text-slate-300 hover:text-white px-3 py-1 bg-white/5 rounded transition-colors hover:bg-white/10">Edit</button>
                           <button onClick={() => handleDelete(item.id)} className="text-xs text-red-400 hover:text-red-300 px-3 py-1 bg-white/5 rounded transition-colors hover:bg-red-500/20">Delete</button>
                        </div>
                      </div>
                    </>
                  ) : (
                    <div className="p-6 flex flex-col h-full">
                      <div className="flex items-center gap-3 mb-4 shrink-0">
                        <div className="w-10 h-10 rounded-full bg-white/10 overflow-hidden">
                           {item.avatar_url ? <img src={item.avatar_url} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-slate-700"></div>}
                        </div>
                        <div>
                          <h4 className="text-white font-bold text-sm">{item.client_name}</h4>
                          <p className="text-slate-500 text-xs">{item.role}</p>
                        </div>
                      </div>
                      <p className="text-slate-300 text-sm mb-4 flex-1 italic">"{item.content}"</p>
                      <div className="flex items-center justify-between border-t border-white/10 pt-4 shrink-0">
                         <span className="text-empathon-rust text-xs font-bold">{item.rating} Stars</span>
                         <div className="flex gap-2">
                            <button onClick={() => handleEdit(item)} className="text-slate-400 hover:text-white text-xs px-2 py-1 rounded hover:bg-white/5">Edit</button>
                            <button onClick={() => handleDelete(item.id)} className="text-red-400 hover:text-red-300 text-xs px-2 py-1 rounded hover:bg-red-500/10">Delete</button>
                         </div>
                      </div>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../utils/supabaseClient';
import { Button } from '../Button';
import { ComponentVariant } from '../../types';

export const CarManager: React.FC = () => {
  const [cars, setCars] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  // Create/Edit Mode State
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);

  // Filter State
  const [filters, setFilters] = useState({
    brand: '',
    status: '',
    min_price: '',
    max_price: '',
    condition: '',
    preorder: false
  });

  // Form State
  const initialFormState = {
    brand: 'Mercedes-Benz',
    model: '',
    year: new Date().getFullYear(),
    price: '',
    mileage: '',
    transmission: 'Automatic',
    fuel_type: 'Petrol',
    status: 'Available',
    condition: 'Used',
    buyer_type: ['Individual'], 
    image_url: ''
  };

  const [formData, setFormData] = useState(initialFormState);
  const [imageFile, setImageFile] = useState<File | null>(null);

  const fetchCars = async () => {
    setLoading(true);
    try {
      let query = supabase
        .from('cars')
        .select('*')
        .order('created_at', { ascending: false });

      if (filters.brand) query = query.eq('brand', filters.brand);
      if (filters.status) query = query.eq('status', filters.status);
      if (filters.condition) query = query.eq('condition', filters.condition);
      if (filters.min_price) query = query.gte('price', filters.min_price);
      if (filters.max_price) query = query.lte('price', filters.max_price);
      if (filters.preorder) query = query.eq('status', 'Pre-Order');

      const { data, error } = await query;

      if (error) throw error;
      setCars(data || []);
    } catch (err) {
      console.error('Error fetching cars:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCars();
  }, [filters, isFormOpen]);

  const handleDelete = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this vehicle? This action cannot be undone.')) {
      const { error } = await supabase.from('cars').delete().eq('id', id);
      if (error) {
        alert('Error deleting vehicle');
        console.error(error);
      } else {
        fetchCars();
      }
    }
  };

  const handleEdit = (car: any) => {
    setFormData({
      brand: car.brand,
      model: car.model,
      year: car.year,
      price: car.price,
      mileage: car.mileage,
      transmission: car.transmission,
      fuel_type: car.fuel_type,
      status: car.status,
      condition: car.condition,
      buyer_type: car.buyer_type || [],
      image_url: car.image_url
    });
    setEditingId(car.id);
    setImageFile(null); // Reset file input
    setIsFormOpen(true);
  };

  const uploadImage = async (file: File): Promise<string> => {
    try {
      setUploading(true);
      const fileExt = file.name.split('.').pop();
      const fileName = `cars/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

      const { error: uploadError } = await supabase.storage
        .from('media')
        .upload(fileName, file);

      if (uploadError) {
        throw uploadError;
      }

      const { data } = supabase.storage.from('media').getPublicUrl(fileName);
      return data.publicUrl;
    } catch (error) {
      console.error('Error uploading image:', error);
      alert('Error uploading image. Check console for details.');
      return '';
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validation: Require image for new cars
    if (!editingId && !imageFile && !formData.image_url) {
      alert("Please upload a vehicle image.");
      return;
    }

    setLoading(true);

    let finalImageUrl = formData.image_url;

    // Handle Image Upload if file selected
    if (imageFile) {
      const uploadedUrl = await uploadImage(imageFile);
      if (uploadedUrl) {
        finalImageUrl = uploadedUrl;
      } else {
        setLoading(false);
        return; // Stop if upload failed
      }
    }

    const payload = {
      ...formData,
      image_url: finalImageUrl,
      price: Number(formData.price),
      mileage: Number(formData.mileage),
      buyer_type: formData.buyer_type
    };

    let error;

    if (editingId) {
      // Update Mode
      const result = await supabase
        .from('cars')
        .update(payload)
        .eq('id', editingId);
      error = result.error;
    } else {
      // Create Mode
      const result = await supabase
        .from('cars')
        .insert([payload]);
      error = result.error;
    }

    if (error) {
      console.error('Error saving car:', error);
      alert(`Failed to save vehicle: ${error.message}`);
    } else {
      setIsFormOpen(false);
      setFormData(initialFormState);
      setImageFile(null);
      setEditingId(null);
      fetchCars();
    }
    setLoading(false);
  };

  const toggleBuyerType = (type: string) => {
    const currentTypes = formData.buyer_type;
    if (currentTypes.includes(type)) {
      setFormData({ ...formData, buyer_type: currentTypes.filter(t => t !== type) });
    } else {
      setFormData({ ...formData, buyer_type: [...currentTypes, type] });
    }
  };

  const inputClass = "w-full bg-black/20 border border-white/10 rounded-lg px-4 py-2 text-white focus:outline-none focus:border-empathon-rust transition-colors";
  const labelClass = "block text-xs text-slate-400 uppercase tracking-widest mb-2";

  return (
    <div className="flex flex-col lg:flex-row gap-6 h-full">

      {isFormOpen ? (
        <div className="w-full bg-white/5 border border-white/10 rounded-2xl p-8 overflow-y-auto">
          <div className="flex justify-between items-center mb-8 border-b border-white/10 pb-4">
             <h2 className="text-2xl font-serif text-white">{editingId ? 'Edit Vehicle' : 'Add New Vehicle'}</h2>
             <button 
               onClick={() => {
                 setIsFormOpen(false);
                 setEditingId(null);
                 setFormData(initialFormState);
                 setImageFile(null);
               }} 
               className="text-slate-400 hover:text-white transition-colors"
             >
               Cancel
             </button>
          </div>

          <form onSubmit={handleSubmit} className="max-w-4xl mx-auto space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelClass}>Brand</label>
                <select 
                  className={inputClass}
                  value={formData.brand}
                  onChange={e => setFormData({...formData, brand: e.target.value})}
                >
                  <option value="Mercedes-Benz">Mercedes-Benz</option>
                  <option value="Toyota">Toyota</option>
                  <option value="Hyundai">Hyundai</option>
                  <option value="Lexus">Lexus</option>
                  <option value="Rolls-Royce">Rolls-Royce</option>
                  <option value="Bentley">Bentley</option>
                  <option value="Porsche">Porsche</option>
                  <option value="Aston Martin">Aston Martin</option>
                </select>
              </div>
              <div>
                <label className={labelClass}>Model</label>
                <input required type="text" className={inputClass} placeholder="e.g. GLE 350" value={formData.model} onChange={e => setFormData({...formData, model: e.target.value})} />
              </div>
              <div>
                <label className={labelClass}>Year</label>
                <input required type="number" className={inputClass} value={formData.year} onChange={e => setFormData({...formData, year: Number(e.target.value)})} />
              </div>
              <div>
                <label className={labelClass}>Condition</label>
                 <select 
                  className={inputClass}
                  value={formData.condition}
                  onChange={e => setFormData({...formData, condition: e.target.value})}
                >
                  <option value="New">New</option>
                  <option value="Used">Used</option>
                  <option value="Certified Pre-Owned">Certified Pre-Owned</option>
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               <div>
                  <label className={labelClass}>Price (₦)</label>
                  <input required type="number" className={inputClass} placeholder="0" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} />
               </div>
               <div>
                  <label className={labelClass}>Mileage</label>
                  <input required type="number" className={inputClass} placeholder="0" value={formData.mileage} onChange={e => setFormData({...formData, mileage: e.target.value})} />
               </div>
               <div>
                  <label className={labelClass}>Status</label>
                  <select className={inputClass} value={formData.status} onChange={e => setFormData({...formData, status: e.target.value})}>
                     <option value="Available">Available</option>
                     <option value="Reserved">Reserved</option>
                     <option value="Pre-Order">Pre-Order</option>
                  </select>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className={labelClass}>Transmission</label>
                <select className={inputClass} value={formData.transmission} onChange={e => setFormData({...formData, transmission: e.target.value})}>
                  <option value="Automatic">Automatic</option>
                  <option value="Manual">Manual</option>
                  <option value="PDK">PDK</option>
                  <option value="E-Drive">E-Drive</option>
                </select>
              </div>
              <div>
                <label className={labelClass}>Fuel Type</label>
                <select className={inputClass} value={formData.fuel_type} onChange={e => setFormData({...formData, fuel_type: e.target.value})}>
                  <option value="Petrol">Petrol</option>
                  <option value="Diesel">Diesel</option>
                  <option value="Hybrid">Hybrid</option>
                  <option value="Electric">Electric</option>
                </select>
              </div>
            </div>

            <div className="p-4 bg-white/5 rounded-xl border border-white/10">
               <label className={labelClass}>Vehicle Image</label>
               <div className="flex gap-4 items-start">
                  <div className="flex-1">
                    <input 
                      type="file" 
                      accept="image/*"
                      className="block w-full text-sm text-slate-400
                        file:mr-4 file:py-2 file:px-4
                        file:rounded-full file:border-0
                        file:text-xs file:font-semibold
                        file:bg-empathon-rust file:text-black
                        hover:file:bg-empathon-rustLight"
                      onChange={(e) => {
                        if (e.target.files && e.target.files[0]) {
                          setImageFile(e.target.files[0]);
                        }
                      }}
                    />
                    <p className="text-[10px] text-slate-500 mt-2">
                       {editingId ? "Upload to replace current image." : "Required."}
                    </p>
                  </div>
                  {(imageFile || formData.image_url) && (
                     <div className="w-24 h-24 rounded-lg bg-black/40 overflow-hidden border border-white/10">
                        <img 
                          src={imageFile ? URL.createObjectURL(imageFile) : formData.image_url} 
                          alt="Preview" 
                          className="w-full h-full object-cover" 
                        />
                     </div>
                  )}
               </div>
            </div>

            <div>
              <label className={labelClass}>Target Market</label>
              <div className="flex gap-4 mt-2">
                 <label className="flex items-center gap-2 cursor-pointer bg-white/5 px-4 py-2 rounded-lg border border-white/10 hover:border-empathon-rust/50 transition-colors">
                    <input type="checkbox" checked={formData.buyer_type.includes('Individual')} onChange={() => toggleBuyerType('Individual')} className="accent-empathon-rust" />
                    <span className="text-sm text-white">Individual</span>
                 </label>
                 <label className="flex items-center gap-2 cursor-pointer bg-white/5 px-4 py-2 rounded-lg border border-white/10 hover:border-empathon-rust/50 transition-colors">
                    <input type="checkbox" checked={formData.buyer_type.includes('Corporate')} onChange={() => toggleBuyerType('Corporate')} className="accent-empathon-rust" />
                    <span className="text-sm text-white">Corporate</span>
                 </label>
              </div>
            </div>

            <div className="pt-6 border-t border-white/10 flex justify-end gap-4">
               <button 
                 type="button" 
                 onClick={() => {
                   setIsFormOpen(false);
                   setEditingId(null);
                   setFormData(initialFormState);
                   setImageFile(null);
                 }} 
                 className="px-6 py-2 rounded-xl text-slate-400 hover:text-white transition-colors"
               >
                 Cancel
               </button>
               <Button type="submit" variant={ComponentVariant.PRIMARY} disabled={loading || uploading}>
                 {loading || uploading ? 'Processing...' : (editingId ? 'Update Vehicle' : 'Add Vehicle')}
               </Button>
            </div>
          </form>
        </div>
      ) : (
        <>
          {/* Filters Panel */}
          <div className="w-full lg:w-64 bg-white/5 border border-white/10 rounded-2xl p-6 h-fit shrink-0">
            <h3 className="text-white font-serif text-lg mb-6 flex items-center gap-2">
              <svg className="w-5 h-5 text-empathon-rust" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
              </svg>
              Filters
            </h3>

            <div className="space-y-4">
              <div>
                <label className="text-xs text-slate-500 uppercase tracking-widest block mb-2">Brand</label>
                <select 
                  value={filters.brand}
                  onChange={(e) => setFilters({...filters, brand: e.target.value})}
                  className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:border-empathon-rust outline-none"
                >
                  <option value="">All Brands</option>
                  <option value="Mercedes-Benz">Mercedes-Benz</option>
                  <option value="Toyota">Toyota</option>
                  <option value="Hyundai">Hyundai</option>
                  <option value="Lexus">Lexus</option>
                  <option value="Rolls-Royce">Rolls-Royce</option>
                </select>
              </div>

              <div>
                <label className="text-xs text-slate-500 uppercase tracking-widest block mb-2">Condition</label>
                <select 
                  value={filters.condition}
                  onChange={(e) => setFilters({...filters, condition: e.target.value})}
                  className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:border-empathon-rust outline-none"
                >
                  <option value="">Any</option>
                  <option value="New">New</option>
                  <option value="Used">Used</option>
                  <option value="Certified Pre-Owned">CPO</option>
                </select>
              </div>

              <div>
                <label className="text-xs text-slate-500 uppercase tracking-widest block mb-2">Status</label>
                <select 
                  value={filters.status}
                  onChange={(e) => setFilters({...filters, status: e.target.value})}
                  className="w-full bg-black/20 border border-white/10 rounded-lg px-3 py-2 text-sm text-white focus:border-empathon-rust outline-none"
                >
                  <option value="">All Statuses</option>
                  <option value="Available">Available</option>
                  <option value="Reserved">Reserved</option>
                  <option value="Pre-Order">Pre-Order</option>
                </select>
              </div>

              <Button 
                variant={ComponentVariant.SECONDARY}
                className="w-full !py-2 !text-xs mt-4"
                onClick={() => setFilters({brand: '', status: '', min_price: '', max_price: '', condition: '', preorder: false})}
              >
                Reset Filters
              </Button>
            </div>
          </div>

          {/* Main Content */}
          <div className="flex-1 bg-white/5 border border-white/10 rounded-2xl p-6 overflow-hidden flex flex-col">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-serif text-white">Vehicle Inventory</h2>
              <Button 
                variant={ComponentVariant.PRIMARY} 
                onClick={() => {
                  setFormData(initialFormState);
                  setEditingId(null);
                  setIsFormOpen(true);
                }} 
                className="!py-2 !px-4 !text-sm flex items-center gap-2"
              >
                <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
                Add Vehicle
              </Button>
            </div>

            <div className="flex-1 overflow-auto">
              <table className="w-full text-left border-collapse">
                <thead className="sticky top-0 bg-[#0F1A36] z-10">
                  <tr className="border-b border-white/10">
                    <th className="py-3 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Image</th>
                    <th className="py-3 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Details</th>
                    <th className="py-3 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Price (₦)</th>
                    <th className="py-3 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider">Status</th>
                    <th className="py-3 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {loading ? (
                    <tr><td colSpan={5} className="py-8 text-center text-slate-500">Loading fleet data...</td></tr>
                  ) : cars.length === 0 ? (
                    <tr><td colSpan={5} className="py-8 text-center text-slate-500">No vehicles found.</td></tr>
                  ) : (
                    cars.map((car) => (
                      <tr key={car.id} className="hover:bg-white/5 transition-colors group">
                        <td className="py-3 px-4">
                          <div className="w-16 h-10 rounded overflow-hidden bg-white/5 border border-white/10">
                             <img src={car.image_url} alt={car.model} className="w-full h-full object-cover" />
                          </div>
                        </td>
                        <td className="py-3 px-4">
                          <div className="text-white font-medium">{car.brand} {car.model}</div>
                          <div className="text-xs text-slate-500">{car.year} • {car.condition} • {car.mileage.toLocaleString()} mi</div>
                        </td>
                        <td className="py-3 px-4 text-slate-300 font-mono">
                          ₦{Number(car.price).toLocaleString()}
                        </td>
                        <td className="py-3 px-4">
                          <span className={`px-2 py-1 rounded text-[10px] uppercase font-bold tracking-wider ${
                            car.status === 'Available' ? 'bg-green-500/10 text-green-500' :
                            car.status === 'Reserved' ? 'bg-red-500/10 text-red-500' :
                            'bg-empathon-rust/10 text-empathon-rust'
                          }`}>
                            {car.status}
                          </span>
                        </td>
                        <td className="py-3 px-4 text-right">
                           <div className="flex items-center justify-end gap-2">
                              <button 
                                onClick={() => handleEdit(car)}
                                className="text-xs text-slate-400 hover:text-white px-2 py-1 bg-white/5 hover:bg-white/10 rounded transition-colors"
                              >
                                Edit
                              </button>
                              <button 
                                onClick={() => handleDelete(car.id)}
                                className="text-xs text-red-400 hover:text-red-300 px-2 py-1 bg-white/5 hover:bg-red-500/20 rounded transition-colors"
                              >
                                Delete
                              </button>
                           </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </div>
  );
};
